'use strict';
function normalizationGain(c){return c.normalization?.enabled?c.normalization.gain:1}
function amplitudeDB(value){return value>0?20*Math.log10(value):-Infinity}
let normalizationAnalysis=null,normalizationBusy=false;
async function analyseClipPeak(c){
 const buffer=audioBuffers.get(c.id);if(!buffer)throw Error('Wait for this audio clip to load.');
 const projectAtStart=project,source=c.src,from=Math.max(0,Math.floor(c.offset*buffer.sampleRate)),to=Math.min(buffer.length,Math.ceil((c.offset+c.duration*(c.rate||1))*buffer.sampleRate));let peak=0,sum=0,count=0;
 for(let channel=0;channel<buffer.numberOfChannels;channel++){const data=buffer.getChannelData(channel);for(let start=from;start<to;start+=500000){for(let i=start;i<Math.min(to,start+500000);i++){const value=data[i];peak=Math.max(peak,Math.abs(value));sum+=value*value;count++}await new Promise(resolve=>requestAnimationFrame(resolve));if(project!==projectAtStart||c.src!==source||audioBuffers.get(c.id)!==buffer)throw Error('The audio changed during analysis. Analyse it again.')}}
 return{clipId:c.id,source,offset:c.offset,duration:c.duration,rate:c.rate||1,peak,rms:Math.sqrt(sum/Math.max(1,count))};
}
function samePeakAnalysis(c,a){return a&&a.clipId===c.id&&a.source===c.src&&a.offset===c.offset&&a.duration===c.duration&&a.rate===(c.rate||1)}
function normalizedClip(){return tracks().find(c=>c.id===$('normalizeSource').value)}
document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openNormalize">Normalize audio</button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="normalizeDialog"><div class="tool-heading"><div><div class="eyebrow">SET A CONSISTENT PEAK LEVEL</div><h2>Audio normalization</h2></div><button id="closeNormalize">Close</button></div><p class="note">Measure the selected clip and adjust its gain toward a peak target. Your source file, fades and Volume setting are preserved.</p><label>Audio clip<select id="normalizeSource"></select></label><div class="pro-tool-row"><label>Target peak (dBFS)<input id="normalizeTarget" type="number" min="-24" max="-0.1" step="0.5" value="-1"></label><button id="analysePeak">Analyse clip</button><button id="applyNormalization" class="primary">Normalize</button></div><div id="normalizationSummary" class="analysis-summary"></div><p class="note">The target applies before the clip's Volume and fades. Final mix level also depends on overlapping tracks. Gain boost is limited to 30 dB; very quiet audio may stay below the target.</p><div class="pro-tool-row"><button id="normalizePlay">Play / pause mix</button><button id="resetNormalization">Reset normalization</button></div></dialog>`);
function renderNormalization(){const c=normalizedClip(),a=samePeakAnalysis(c||{},normalizationAnalysis)?normalizationAnalysis:null;for(const id of ['analysePeak','applyNormalization','resetNormalization','normalizeSource','normalizeTarget'])$(id).disabled=normalizationBusy||(!c&&id!=='normalizeSource');const summary=$('normalizationSummary');summary.replaceChildren();if(!c){summary.textContent='Add audio to the timeline to normalize it.';return}const line=document.createElement('p');line.textContent=c.name+' · '+c.duration.toFixed(2)+'s · current gain '+amplitudeDB(normalizationGain(c)).toFixed(1)+' dB';summary.append(line);if(a){const measured=document.createElement('p');measured.textContent=a.peak<.00001?'This section is silent.':('Source peak '+amplitudeDB(a.peak).toFixed(1)+' dBFS · RMS '+amplitudeDB(a.rms).toFixed(1)+' dBFS');summary.append(measured)}else summary.append(document.createTextNode('Analyse this clip to see its source peak. Analyse again after changing its source timing.'))}
async function runNormalization(apply){const c=normalizedClip();if(!c||normalizationBusy)return;stop();normalizationBusy=true;window.editorTaskBusy=true;renderNormalization();$('normalizationSummary').textContent='Measuring audio…';try{const a=samePeakAnalysis(c,normalizationAnalysis)?normalizationAnalysis:await analyseClipPeak(c);normalizationAnalysis=a;if(apply){if(a.peak<.00001)throw Error('This section is silent. There is no signal to normalize.');const target=clamp(Number($('normalizeTarget').value)||-1,-24,-.1),gain=clamp(Math.pow(10,target/20)/a.peak,.01,Math.pow(10,30/20));c.normalization={enabled:true,gain,target,peak:a.peak};save();render();toast('Normalization applied. Volume, fades and ducking still apply.')}}catch(e){toast(e.message)}finally{normalizationBusy=false;window.editorTaskBusy=false;renderNormalization()}}
$('openNormalize').onclick=()=>{stop();const select=$('normalizeSource');select.replaceChildren();for(const c of tracks()){const option=document.createElement('option');option.value=c.id;option.textContent=c.name;select.append(option)}select.value=selectedAudio||tracks().find(c=>c.videoId===selected)?.id||tracks()[0]?.id||'';const c=normalizedClip();$('normalizeTarget').value=c?.normalization?.target??-1;renderNormalization();$('normalizeDialog').showModal()};$('closeNormalize').onclick=()=>{stop();$('normalizeDialog').close()};$('normalizeDialog').addEventListener('cancel',e=>{if(normalizationBusy)e.preventDefault();else stop()});$('normalizeSource').onchange=()=>{normalizationAnalysis=null;$('normalizeTarget').value=normalizedClip()?.normalization?.target??-1;renderNormalization()};$('analysePeak').onclick=()=>runNormalization(false);$('applyNormalization').onclick=()=>runNormalization(true);$('normalizePlay').onclick=()=>{if(!normalizationBusy)play()};$('resetNormalization').onclick=()=>{if(normalizationBusy)return;const c=normalizedClip();if(c){stop();delete c.normalization;save();render();renderNormalization()}};
const settingsBeforeNormalization=renderClipSettings;renderClipSettings=function(){settingsBeforeNormalization();const c=tracks().find(c=>c.id===selectedAudio);if(!c)return;const button=document.createElement('button');button.id='clipNormalize';button.textContent=c.normalization?.enabled?'Normalize · '+amplitudeDB(c.normalization.gain).toFixed(1)+' dB':'Normalize audio';button.onclick=()=>$('openNormalize').click();$('clipSettings').append(button)};
const normalizationValidator=valid;valid=function(p){return normalizationValidator(p)&&(p.audioClips||[]).every(c=>!c.normalization||typeof c.normalization.enabled==='boolean'&&Number.isFinite(c.normalization.gain)&&c.normalization.gain>=.01&&c.normalization.gain<=32&&Number.isFinite(c.normalization.target)&&c.normalization.target>=-24&&c.normalization.target<=-.1&&Number.isFinite(c.normalization.peak)&&c.normalization.peak>=0&&c.normalization.peak<=100)};
render();
